-- PROPOSTA (checkup-geral-15-11, B3.7): os primeiros 11 produtos da Loja Online (nicho Pets).
-- Quem aplica: Claude.ai. Ordem do Danilo 15/11 17:53; regra de preco AUTORIZO 14/11/2026 12:19:
-- preco no Bora = 2 x custo do fornecedor. Custo = produto + envio para Portugal na CJ (CJPacket
-- Ordinary I), em dolares convertidos a 0.90481 EUR (BCE 13/11/2026), pesquisa da CJ de 15/11
-- (C:/BoraLocal/LojaShopify/PESQUISA-CJ-15-11.md). Fotos = as da propria ficha da CJ (lidas a 15/11
-- ~18:40, todas responderam 200 image/*). Prazo honesto: tudo sai do armazem da CJ na China
-- (1-3 dias de preparacao + 5-11 dias para 57% dos pedidos, 12-14 para 28%): 7 a 17 dias uteis.
-- Nenhum tem armazem na UE na CJ para estes artigos (visto na pesquisa); fica anotado.
-- Fora: comida, suplementos, quimicos e eletricos. Cama e arranhador ficaram fora (envio pesado).
-- shopify_product_id leva 'cj:<pid da CJ>' ate a Shopify ter os produtos (a sincronizacao troca).
-- Entram ativos (o cliente so os ve com a loja visivel para ele: lista de permissao ou interruptor).

insert into public.loja_online_produtos
  (shopify_product_id, shopify_variant_id, titulo, descricao, imagens, custo_fornecedor_cents,
   preco_bora_cents, prazo_min_dias, prazo_max_dias, destaque, nicho_id, ativo)
select v.spid, v.sku, v.titulo, v.descricao, v.imagens, v.custo, v.preco, v.pmin, v.pmax, v.destaque,
       n.id, true
from (values
  ('cj:6AEB0AAE-3E70-4EAE-857B-B83389786B3A:S', 'CJJJCWGY01342-Grey No Logo-S', 'Copo limpa-patas portátil (pequeno)', 'Patas limpas antes de entrar em casa. Põe água, mete a pata, roda e seca. As cerdas macias de silicone tiram a lama sem magoar. Leve para levar no carro. Tamanho pequeno, para cães pequenos e gatos.', array['https://oss-cf.cjdropshipping.com/product/2026/08/11/05/c233f2f0-2fb6-4bf6-bc01-594e770d1c1b.jpg', 'https://cf.cjdropshipping.com/20200420/458688025043.jpg', 'https://cf.cjdropshipping.com/20200420/2690306010517.jpg', 'https://cf.cjdropshipping.com/20200417/2406488160295.jpg']::text[], 928, 1856, 7, 17, true),
  ('cj:6AEB0AAE-3E70-4EAE-857B-B83389786B3A:L', 'CJJJCWGY01342-Grey No Logo-L', 'Copo limpa-patas portátil (grande)', 'Patas limpas antes de entrar em casa. Põe água, mete a pata, roda e seca. As cerdas macias de silicone tiram a lama sem magoar. Tamanho grande, para cães médios e grandes.', array['https://oss-cf.cjdropshipping.com/product/2026/08/11/05/c233f2f0-2fb6-4bf6-bc01-594e770d1c1b.jpg', 'https://cf.cjdropshipping.com/20200417/41972025398.jpg', 'https://cf.cjdropshipping.com/20200417/2177198792634.jpg', 'https://cf.cjdropshipping.com/20200420/2690306010517.jpg']::text[], 1102, 2204, 7, 17, false),
  ('cj:C6DD91F5-4F23-4D6D-9EB4-0A5F88D484A1', 'CJJJJTJT41249-White', 'Rolo tira-pelos reutilizável', 'Tira os pelos do sofá, da cama e da roupa sem fitas adesivas. Esvazia-se com um clique e volta a usar-se as vezes que quiseres.', array['https://cf.cjdropshipping.com/203208/4826473683679.jpg', 'https://cf.cjdropshipping.com/203208/3428635116715.jpg', 'https://cf.cjdropshipping.com/203208/1111694400165.jpg', 'https://cf.cjdropshipping.com/203208/579226107514.jpg']::text[], 825, 1650, 7, 17, true),
  ('cj:2503191148021601200', 'CJYD233200837KP', 'Luva de escovar o pelo', 'Escova e faz festas ao mesmo tempo. As pontas de silicone apanham o pelo solto de cães, gatos e coelhos, e o teu patudo nem dá por isso. Uma luva, cor preta.', array['https://oss-cf.cjdropshipping.com/product/2025/05/26/06/6b2a1028-7824-48d5-ab95-a342d69ec7cc.jpg', 'https://oss-cf.cjdropshipping.com/product/2025/05/26/06/6553fa78-1ea3-40b6-a1b0-954a5a6a5d08.jpg', 'https://oss-cf.cjdropshipping.com/product/2025/05/26/06/5370fe9f-8d30-46d6-ad73-3817771f7cac.jpg', 'https://oss-cf.cjdropshipping.com/product/2025/05/26/06/1e41ba3d-928e-4287-986f-03f8e18f1f09.jpg']::text[], 475, 950, 7, 17, true),
  ('cj:1595721401296760832', 'CJHS162047424XC', 'Garrafa de água portátil 2 em 1', 'Garrafa e bebedouro na mesma peça, 240 ml. Carrega-se no botão para encher o bebedouro e a água que sobra volta para dentro. Para passeios e viagens.', array['https://cf.cjdropshipping.com/da845084-2fdb-474d-a7a8-4d89db938831.jpg', 'https://cf.cjdropshipping.com/fcc0adca-5065-4674-9b62-32d609bb2d81.jpg', 'https://cf.cjdropshipping.com/31ec37b2-3e30-465f-a9fa-f15043279a41.jpg', 'https://cf.cjdropshipping.com/27398ef7-e77b-49aa-bedd-e879970c3f47.jpg']::text[], 946, 1892, 7, 17, false),
  ('cj:1644945472383094784', 'CJMY172938501AZ', 'Túnel dobrável para gatos', 'Túnel com três saídas e uma bola pendurada para brincar e se esconder. Dobra-se e guarda-se numa gaveta.', array['https://cf.cjdropshipping.com/be7a1d48-a4e5-4adb-b5be-7dc65d574465.jpg', 'https://cf.cjdropshipping.com/d0d3a8b7-492a-4263-bb6d-19ad582242b1.jpg', 'https://cf.cjdropshipping.com/3a811e15-2cb8-4238-abc6-70ea71b67027.jpg', 'https://cf.cjdropshipping.com/f24c27a4-c10e-4b6b-a6cd-b40983b0201d.jpg']::text[], 1034, 2068, 7, 17, false),
  ('cj:1402533508353757184', 'CJGY116692305EV', 'Tapete de lamber com ventosa', 'Barra-se com iogurte ou patê e prende-se ao azulejo com as ventosas. O teu patudo fica entretido no banho, no corte de unhas ou quando ficas fora.', array['https://cf.cjdropshipping.com/1623224705565.jpg', 'https://cf.cjdropshipping.com/1623224705562.jpg', 'https://cf.cjdropshipping.com/1623224705566.jpg', 'https://cf.cjdropshipping.com/1623224705564.jpg']::text[], 669, 1338, 7, 17, false),
  ('cj:2E961E18-A6DD-44AC-A9B4-37795039890F', 'CJJJCWGY00144-Black-Centre', 'Bola de snacks com som', 'Põe os biscoitos lá dentro: o teu cão rola a bola, ela faz um som divertido e os snacks vão caindo. Brincadeira sem pilhas. Tamanho médio.', array['https://cf.cjdropshipping.com/15265152/8148685032169.jpg', 'https://cf.cjdropshipping.com/203209/278748581230.jpg', 'https://cf.cjdropshipping.com/203209/1281435688203.png', 'https://cf.cjdropshipping.com/203209/1468363838993.jpg']::text[], 712, 1424, 7, 17, false),
  ('cj:1653041912300969984', 'CJGY174846501AZ', 'Comedouro lento (labirinto)', 'Labirinto que faz o teu cão ou gato comer devagar e com calma. Base antiderrapante.', array['https://cf.cjdropshipping.com/3d15f29e-52f2-4d5f-bfd5-e5eedb851eec.jpg', 'https://cf.cjdropshipping.com/f49c878f-845e-4c98-a4e9-108c8406179e.jpeg', 'https://cf.cjdropshipping.com/874ab992-b94e-4ec8-b48d-9f100899cddf.jpg', 'https://cf.cjdropshipping.com/9c15aae8-2d00-4b68-9264-b8f998457982.jpeg']::text[], 902, 1804, 7, 17, false),
  ('cj:1836302458034212864', 'CJGY214044402BY', 'Tigela dobrável de silicone com mosquetão', 'Fecha-se como um disco e vai presa à trela com o mosquetão. Para água e comida nos passeios e viagens. Cor-de-rosa, em forma de flor.', array['https://cf.cjdropshipping.com/a15d3ec3-cafc-4839-a57d-d5af45f0633d.jpg', 'https://cf.cjdropshipping.com/1d1102d5-4c2c-40b2-8635-b0b0fc37e636.jpg', 'https://cf.cjdropshipping.com/50697a7b-5d25-4e7d-bd77-8bb7f63217e9.jpg', 'https://cf.cjdropshipping.com/04c981b1-4bd6-4469-8f9e-bb3d12fbc70e.jpg']::text[], 734, 1468, 7, 17, false),
  ('cj:4D6E5E7A-85A5-4F26-955F-C91C69F19561', 'CJJJCWGY03316-Dark Grey', 'Porta-sacos para a trela', 'Bolsa de tecido que se prende à trela e deixa tirar um saco de cada vez. Cor cinzento-escuro.', array['https://cf.cjdropshipping.com/203008/1889608131657.jpg', 'https://cf.cjdropshipping.com/203008/244671980038.jpg', 'https://cf.cjdropshipping.com/203008/1555472543913.jpg', 'https://cf.cjdropshipping.com/203008/13985340699750.jpg']::text[], 510, 1020, 7, 17, false)
) as v(spid, sku, titulo, descricao, imagens, custo, preco, pmin, pmax, destaque)
cross join (select id from public.loja_online_nichos where slug = 'pets') n
on conflict (shopify_product_id) do nothing;

-- Prova: 11 linhas, preco = 2 x custo em todas.
